allocation_rules_kind_values_check.value:
(
        "allocation_rules"."kind" = 'fixed' and "allocation_rules"."amount" is not null and "allocation_rules"."amount" > 0 and "allocation_rules"."percent" is null
      ) or (
        "allocation_rules"."kind" = 'percentage' and "allocation_rules"."percent" is not null and "allocation_rules"."percent" > 0 and "allocation_rules"."percent" <= 1 and "allocation_rules"."amount" is null
      ) or (
        "allocation_rules"."kind" = 'remainder' and "allocation_rules"."amount" is null and "allocation_rules"."percent" is null
      )

corporate_actions_kind_values_check.value:
(
        "corporate_actions"."kind" = 'BONUS' and "corporate_actions"."quantity" is not null and "corporate_actions"."quantity" > 0 and "corporate_actions"."ratio" is null
      ) or (
        "corporate_actions"."kind" = 'SPLIT' and "corporate_actions"."ratio" is not null and "corporate_actions"."ratio" > 0 and "corporate_actions"."quantity" is null
      ) or (
        "corporate_actions"."kind" = 'WRITE_OFF' and "corporate_actions"."quantity" is null and "corporate_actions"."ratio" is null
      )

goal_allocation_events_shape_check.value:
(
        "goal_allocation_events"."account_id" is not null and "goal_allocation_events"."holding_id" is null and "goal_allocation_events"."percent_delta" is null
      ) or (
        "goal_allocation_events"."holding_id" is not null and "goal_allocation_events"."account_id" is null and "goal_allocation_events"."percent_delta" is not null and "goal_allocation_events"."percent_delta" <> 0
      )

transactions_quantity_price_check.value:
(
        "transactions"."type" in ('INVESTMENT_PURCHASE', 'INVESTMENT_SALE') and "transactions"."holding_id" is not null
          and (
            ("transactions"."quantity" is not null and "transactions"."quantity" > 0 and "transactions"."unit_price" is not null and "transactions"."unit_price" >= 0)
            or ("transactions"."quantity" is null and "transactions"."unit_price" is null)
          )
      ) or (
        ("transactions"."type" not in ('INVESTMENT_PURCHASE', 'INVESTMENT_SALE') or "transactions"."holding_id" is null)
          and "transactions"."quantity" is null and "transactions"."unit_price" is null
      )
